'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let inputIndex = 0;

function nextInt() {
  while (inputIndex < input.length && input.charCodeAt(inputIndex) <= 32) inputIndex++;
  let value = 0;
  while (inputIndex < input.length) {
    const c = input.charCodeAt(inputIndex);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    inputIndex++;
  }
  return value;
}

const N = nextInt();
const parent = new Int32Array(N + 1);
parent[1] = 1;

const head = new Int32Array(N + 1);
const next = new Int32Array(N + 1);

for (let i = 2; i <= N; i++) {
  parent[i] = nextInt();
  next[i] = head[parent[i]];
  head[parent[i]] = i;
}

const size = new Int32Array(N + 1);
size.fill(1);
for (let i = N; i >= 2; i--) size[parent[i]] += size[i];

const tin = new Int32Array(N + 1);
const stack = new Int32Array(N);
let top = 0;
let timer = 0;
stack[top++] = 1;

while (top > 0) {
  const v = stack[--top];
  tin[v] = timer++;
  for (let child = head[v]; child !== 0; child = next[child]) {
    stack[top++] = child;
  }
}

const LOG = Math.ceil(Math.log2(N + 1));
const originalUp = new Array(LOG);
originalUp[0] = parent;

for (let level = 1; level < LOG; level++) {
  const prev = originalUp[level - 1];
  const curr = new Int32Array(N + 1);
  for (let v = 1; v <= N; v++) curr[v] = prev[prev[v]];
  originalUp[level] = curr;
}

const segments = new Array(LOG);
for (let level = 0; level < LOG; level++) {
  const tree = new Int32Array(4 * N + 5);
  tree.fill(-1);
  segments[level] = tree;
}

function rangeAssign(tree, node, left, right, ql, qr, value) {
  if (ql <= left && right <= qr) {
    tree[node] = value;
    return;
  }

  if (tree[node] !== -1) {
    const valueAtNode = tree[node];
    tree[node * 2] = valueAtNode;
    tree[node * 2 + 1] = valueAtNode;
    tree[node] = -1;
  }

  const mid = (left + right) >> 1;
  if (ql <= mid) rangeAssign(tree, node * 2, left, mid, ql, qr, value);
  if (qr > mid) rangeAssign(tree, node * 2 + 1, mid + 1, right, ql, qr, value);
}

function getJump(level, v) {
  const tree = segments[level];
  const pos = tin[v];
  let node = 1;
  let left = 0;
  let right = N - 1;

  while (true) {
    if (tree[node] !== -1) return tree[node];
    if (left === right) return originalUp[level][v];

    const mid = (left + right) >> 1;
    if (pos <= mid) {
      node *= 2;
      right = mid;
    } else {
      node = node * 2 + 1;
      left = mid + 1;
    }
  }
}

const Q = nextInt();
const answers = [];

for (let i = 0; i < Q; i++) {
  const type = nextInt();
  const v = nextInt();

  if (type === 1) {
    let k = nextInt();
    let current = v;
    let level = 0;

    while (k > 0) {
      if (k & 1) current = getJump(level, current);
      k >>= 1;
      level++;
    }

    answers.push(String(current));
  } else {
    const left = tin[v] + 1;
    const right = tin[v] + size[v] - 1;

    if (left <= right) {
      for (let level = 0; level < LOG; level++) {
        const value = level === 0 ? v : getJump(level - 1, v);
        rangeAssign(segments[level], 1, 0, N - 1, left, right, value);
      }
    }
  }
}

console.log(answers.join('\n'));
